-- V4 : 규칙 기반 품질 검사 실행·결과 저장 구조 (AI-6 2차, 2026-11-26 — docs/completed/ai-metadata-quality-diagnosis.md, 확정 정책 AI6-D01~D35)
-- 판정은 M-5 규칙(StandardizationRule 16개)을 그대로 쓰고, 이 마이그레이션은 실행·결과·규칙 설정·이력만 저장한다. 규칙 정의(코드·대상·심각도)는 코드에 있고 DB 에 두지 않는다.
-- ① TB_INSP_RULE_STNG (검사 규칙 설정) : 프로젝트가 기본값(전부 활성)에서 바꾼 규칙만 둔다 (AI6-D05). 행이 없으면 활성.
-- ② TB_INSP_EXCN (검사 실행) : 수동 전체 검사 1회 = 1행. 상태 PENDING → RUNNING → COMPLETED / FAILED, 재시작 시 INTERRUPTED (AI6-D08).
--   진행 중(PENDING·RUNNING) 실행은 프로젝트마다 하나 — PRGRS_PRJ_SN(진행 중일 때만 PRJ_SN) 의 UNIQUE 로 DB 가 막는다 (원본 수집 PRGRS_CNTN_SN 과 같은 방식, 조건부 인덱스를 쓰지 않는다).
--   REG_DT = 요청 일시(DMND_DT 와 같다), BGNG_DT = 실행 시작, CRTR_DT = 검사 기준 시각(읽기 스냅숏을 잡은 시각, AI6-D27), END_DT = 끝난 시각.
-- ③ TB_INSP_EXCN_RULE (검사 실행 규칙) : 실행 시작 때 확정한 적용 규칙(AI6-D28)과 규칙별 실행 상태·발견 수.
-- ④ TB_INSP_EXCN_RSLT (검사 실행 결과) : 실행 × 규칙 × 변화 유형별 건수 (NEW·PERSISTING·REOPENED·RULE_SATISFIED·TARGET_DELETED·EXCLUDED).
-- ⑤ TB_INSP_RSLT (검사 결과) : 지금의 Finding — 프로젝트 안에서 fingerprint(HASH_VL) 하나에 한 행. 실제 문제 상태(STTS_CD)와 예외 여부(EXCL_YN)를 나눈다 (AI6-D12·D24).
--   상세 근거는 JSONB (AI6-D17·D30). 대상(컬럼·테이블·스키마·용어)에는 FK 를 두지 않는다 — 대상이 지워져도 해결 기록이 남아야 한다 (TARGET_DELETED, AI6-D13).
--   저장 구조 (AI-6 FINAL 최종 보완, AI6-FC-01~03) : fillfactor 80, 최종 실행(LAST_INSP_EXCN_SN)에는 인덱스를 두지 않는다 — 실행마다 모든 유지 결과가 이 값만 바꾸므로
--   인덱스가 있으면 HOT 갱신이 될 수 없다 (FK_INSP_RSLT_02 는 그대로). 근거 : docs/completed/ai-metadata-quality-diagnosis.md 48.5·49장.
-- ⑥ TB_INSP_RSLT_HSTRY (검사 결과 이력) : 예외 처리·예외 해제·재발만 (AI6-D15). 재발 행은 직전 해결(종료 사유·종료 일시)을 함께 남긴다 — 재발하면 검사 결과의 종료 칼럼은 비운다. 자동 삭제 없음.
-- 이름 (표준 사전 확인 2026-11-26) : 검사(INSP)·실행(EXCN)·결과(RSLT)·규칙(RULE)·설정(STNG)·이력(HSTRY)·상태(STTS)·예외(EXCL)·근거(EVDNC)·해시(HASH)·확인(IDNTY)·종료(END)·사유(RSN)·
--   진행(PRGRS)·요청(DMND)·기준(CRTR)·최종(LAST)·변경(CHG)·대상(TRGT) 은 예제 사전에 있고, 새 단어는 공통표준단어 최초(FRST)·등급(GRD) 둘이다. 새 도메인 둘 : 코드V50(규칙 코드 최대 28자), 내용J(JSONB).
-- V0~V3 은 바꾸지 않는다. 기존 행을 바꾸거나 지우지 않는다.

create sequence SQ_INSP_RULE_STNG start with 1 increment by 50;
create table TB_INSP_RULE_STNG (
    INSP_RULE_STNG_SN bigint not null,
    PRJ_SN bigint not null,
    RULE_CD varchar(50) not null,
    ACTVTN_YN boolean not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_INSP_RULE_STNG primary key (INSP_RULE_STNG_SN)
);
alter table TB_INSP_RULE_STNG add constraint UX_INSP_RULE_STNG_01 unique (PRJ_SN, RULE_CD);

create sequence SQ_INSP_EXCN start with 1 increment by 50;
create table TB_INSP_EXCN (
    INSP_EXCN_SN bigint not null,
    PRJ_SN bigint not null,
    PRGRS_PRJ_SN bigint,
    ACNT_SN bigint not null,
    EXCN_STTS_CD varchar(20) not null,
    DMND_DT timestamp(6) not null,
    BGNG_DT timestamp(6),
    CRTR_DT timestamp(6),
    END_DT timestamp(6),
    ERR_CD varchar(100),
    ERR_CN TEXT,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_INSP_EXCN primary key (INSP_EXCN_SN)
);
alter table TB_INSP_EXCN add constraint UX_INSP_EXCN_01 unique (PRGRS_PRJ_SN);
alter table TB_INSP_EXCN add constraint UX_INSP_EXCN_02 unique (INSP_EXCN_SN, PRJ_SN);
create index IX_INSP_EXCN_01 on TB_INSP_EXCN (PRJ_SN, DMND_DT);

create sequence SQ_INSP_EXCN_RULE start with 1 increment by 50;
create table TB_INSP_EXCN_RULE (
    INSP_EXCN_RULE_SN bigint not null,
    INSP_EXCN_SN bigint not null,
    RULE_CD varchar(50) not null,
    EXCN_STTS_CD varchar(20) not null,
    RSLT_CNT integer,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_INSP_EXCN_RULE primary key (INSP_EXCN_RULE_SN)
);
alter table TB_INSP_EXCN_RULE add constraint UX_INSP_EXCN_RULE_01 unique (INSP_EXCN_SN, RULE_CD);
alter table TB_INSP_EXCN_RULE add constraint FK_INSP_EXCN_RULE_01 foreign key (INSP_EXCN_SN) references TB_INSP_EXCN;

create sequence SQ_INSP_EXCN_RSLT start with 1 increment by 50;
create table TB_INSP_EXCN_RSLT (
    INSP_EXCN_RSLT_SN bigint not null,
    INSP_EXCN_SN bigint not null,
    RULE_CD varchar(50) not null,
    CHG_TYPE_CD varchar(20) not null,
    RSLT_CNT integer not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_INSP_EXCN_RSLT primary key (INSP_EXCN_RSLT_SN)
);
alter table TB_INSP_EXCN_RSLT add constraint UX_INSP_EXCN_RSLT_01 unique (INSP_EXCN_SN, RULE_CD, CHG_TYPE_CD);
alter table TB_INSP_EXCN_RSLT add constraint FK_INSP_EXCN_RSLT_01 foreign key (INSP_EXCN_SN) references TB_INSP_EXCN;

create sequence SQ_INSP_RSLT start with 1 increment by 50;
create table TB_INSP_RSLT (
    INSP_RSLT_SN bigint not null,
    PRJ_SN bigint not null,
    RULE_CD varchar(50) not null,
    RSLT_GRD_CD varchar(20) not null,
    TRGT_TYPE_CD varchar(20) not null,
    TRGT_SN bigint not null,
    TBL_SN bigint,
    TRGT_CN TEXT not null,
    HASH_VL varchar(255) not null,
    STTS_CD varchar(20) not null,
    EXCL_YN boolean not null,
    LAST_CHG_TYPE_CD varchar(20) not null,
    END_RSN_CD varchar(20),
    RSLT_EVDNC_CN jsonb not null,
    FRST_IDNTY_DT timestamp(6) not null,
    LAST_IDNTY_DT timestamp(6) not null,
    END_DT timestamp(6),
    FRST_INSP_EXCN_SN bigint not null,
    LAST_INSP_EXCN_SN bigint not null,
    VER_NO bigint not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_INSP_RSLT primary key (INSP_RSLT_SN)
) with (fillfactor = 80);
alter table TB_INSP_RSLT add constraint UX_INSP_RSLT_01 unique (PRJ_SN, HASH_VL);
alter table TB_INSP_RSLT add constraint UX_INSP_RSLT_02 unique (INSP_RSLT_SN, PRJ_SN);
create index IX_INSP_RSLT_01 on TB_INSP_RSLT (PRJ_SN, STTS_CD, RSLT_GRD_CD);
create index IX_INSP_RSLT_02 on TB_INSP_RSLT (PRJ_SN, RULE_CD);
create index IX_INSP_RSLT_03 on TB_INSP_RSLT (PRJ_SN, TRGT_TYPE_CD, TRGT_SN);
create index IX_INSP_RSLT_04 on TB_INSP_RSLT (FRST_INSP_EXCN_SN);
alter table TB_INSP_RSLT add constraint FK_INSP_RSLT_01 foreign key (FRST_INSP_EXCN_SN, PRJ_SN) references TB_INSP_EXCN (INSP_EXCN_SN, PRJ_SN);
alter table TB_INSP_RSLT add constraint FK_INSP_RSLT_02 foreign key (LAST_INSP_EXCN_SN, PRJ_SN) references TB_INSP_EXCN (INSP_EXCN_SN, PRJ_SN);

create sequence SQ_INSP_RSLT_HSTRY start with 1 increment by 50;
create table TB_INSP_RSLT_HSTRY (
    INSP_RSLT_HSTRY_SN bigint not null,
    INSP_RSLT_SN bigint not null,
    PRJ_SN bigint not null,
    INSP_EXCN_SN bigint,
    CHG_TYPE_CD varchar(20) not null,
    STTS_CD varchar(20) not null,
    EXCL_YN boolean not null,
    CHG_RSN_CN varchar(1000),
    END_RSN_CD varchar(20),
    END_DT timestamp(6),
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_INSP_RSLT_HSTRY primary key (INSP_RSLT_HSTRY_SN)
);
create index IX_INSP_RSLT_HSTRY_01 on TB_INSP_RSLT_HSTRY (INSP_RSLT_SN);
create index IX_INSP_RSLT_HSTRY_02 on TB_INSP_RSLT_HSTRY (INSP_EXCN_SN);
alter table TB_INSP_RSLT_HSTRY add constraint FK_INSP_RSLT_HSTRY_01 foreign key (INSP_RSLT_SN, PRJ_SN) references TB_INSP_RSLT (INSP_RSLT_SN, PRJ_SN);
alter table TB_INSP_RSLT_HSTRY add constraint FK_INSP_RSLT_HSTRY_02 foreign key (INSP_EXCN_SN, PRJ_SN) references TB_INSP_EXCN (INSP_EXCN_SN, PRJ_SN);

alter table TB_INSP_EXCN add constraint CK_INSP_EXCN_01 check (EXCN_STTS_CD in ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED', 'INTERRUPTED'));
alter table TB_INSP_EXCN add constraint CK_INSP_EXCN_02 check ((EXCN_STTS_CD in ('PENDING', 'RUNNING') and PRGRS_PRJ_SN is not null and PRGRS_PRJ_SN = PRJ_SN)
    or (EXCN_STTS_CD in ('COMPLETED', 'FAILED', 'INTERRUPTED') and PRGRS_PRJ_SN is null and END_DT is not null));
alter table TB_INSP_EXCN_RULE add constraint CK_INSP_EXCN_RULE_01 check (EXCN_STTS_CD in ('RUNNING', 'COMPLETED', 'FAILED'));
alter table TB_INSP_EXCN_RSLT add constraint CK_INSP_EXCN_RSLT_01 check (CHG_TYPE_CD in ('NEW', 'PERSISTING', 'REOPENED', 'RULE_SATISFIED', 'TARGET_DELETED', 'EXCLUDED'));
alter table TB_INSP_EXCN_RSLT add constraint CK_INSP_EXCN_RSLT_02 check (RSLT_CNT >= 0);
alter table TB_INSP_RSLT add constraint CK_INSP_RSLT_01 check (RSLT_GRD_CD in ('ERROR', 'WARNING', 'INFO'));
alter table TB_INSP_RSLT add constraint CK_INSP_RSLT_02 check (TRGT_TYPE_CD in ('COLUMN', 'TABLE', 'SCHEMA', 'TERM'));
alter table TB_INSP_RSLT add constraint CK_INSP_RSLT_03 check (LAST_CHG_TYPE_CD in ('NEW', 'PERSISTING', 'REOPENED', 'RESOLVED'));
alter table TB_INSP_RSLT add constraint CK_INSP_RSLT_04 check ((STTS_CD = 'OPEN' and END_RSN_CD is null and END_DT is null and LAST_CHG_TYPE_CD <> 'RESOLVED')
    or (STTS_CD = 'RESOLVED' and END_RSN_CD in ('RULE_SATISFIED', 'TARGET_DELETED') and END_DT is not null and LAST_CHG_TYPE_CD = 'RESOLVED'));
alter table TB_INSP_RSLT add constraint CK_INSP_RSLT_05 check (jsonb_typeof(RSLT_EVDNC_CN) = 'object');
alter table TB_INSP_RSLT_HSTRY add constraint CK_INSP_RSLT_HSTRY_01 check ((CHG_TYPE_CD in ('EXCLUDE', 'UNEXCLUDE') and CHG_RSN_CN is not null and INSP_EXCN_SN is null and END_RSN_CD is null and END_DT is null)
    or (CHG_TYPE_CD = 'REOPEN' and CHG_RSN_CN is null and INSP_EXCN_SN is not null and END_RSN_CD in ('RULE_SATISFIED', 'TARGET_DELETED') and END_DT is not null));
alter table TB_INSP_RSLT_HSTRY add constraint CK_INSP_RSLT_HSTRY_02 check (STTS_CD in ('OPEN', 'RESOLVED'));

