-- ---------- 예제 : 물리 모델 TB_INSP_RULE_STNG ----------
-- ---------- 예제 : 논리 모델 검사 규칙 설정 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 검사 규칙 설정 ----------
-- ---------- 예제 : UNIQUE·CHECK 제약조건 검사 규칙 설정 ----------
-- ---------- 예제 : 업무 설명 검사 규칙 설정 ----------
update TB_TBL set TASK_EXPLN = '프로젝트에서 사용 여부를 바꾼 품질 검사 규칙만 기록한다 (AI6-D05). 규칙의 코드·대상·심각도는 서버의 규칙 정의가 정하고 프로젝트마다 바꿀 수 있는 것은 사용 여부뿐이다 (AI6-D06). 기본값(활성)으로 되돌리면 행을 지운다. 설정을 바꿔도 검사를 자동으로 실행하지 않으며, 끈 규칙의 기존 검사 결과는 지우거나 해결로 바꾸지 않는다 (AI6-D14).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '검사 규칙 설정을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and COL_NM = 'INSP_RULE_STNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '설정이 속한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '설정을 바꾼 품질 검사 규칙 (서버 규칙 정의의 코드).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and COL_NM = 'RULE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 프로젝트에서 규칙을 쓰는지 여부. 행이 없으면 활성이다.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and COL_NM = 'ACTVTN_YN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 처음 저장한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 고친 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 처음 저장한 사용자 아이디 (서버 작업은 SYSTEM).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 고친 사용자 아이디 (서버 작업은 SYSTEM).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RULE_STNG' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;

-- ---------- 예제 : 물리 모델 TB_INSP_EXCN ----------
-- ---------- 예제 : 논리 모델 검사 실행 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 검사 실행 ----------
-- ---------- 예제 : UNIQUE·CHECK 제약조건 검사 실행 ----------
-- ---------- 예제 : 인덱스 검사 실행 (V4 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 검사 실행 ----------
update TB_TBL set TASK_EXPLN = '사용자가 요청한 품질 검사(프로젝트 전체, AI6-D07)를 한 행으로 기록한다. 서버 안의 실행기가 차례로 처리하고(AI6-D08·D23), 프로젝트마다 진행 중인 실행은 하나다 (AI6-D18). 검사 기준 일시는 일관된 읽기 스냅숏을 잡은 시각이며 결과는 그 시점의 모델을 판정한 것이다 (AI6-D27). 실패·중단된 실행은 결과를 바꾸지 않으며 다시 실행하지 않는다 (AI6-D33).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '검사 실행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'INSP_EXCN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '검사한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '실행이 대기·진행 중일 때만 프로젝트 일련번호를 담는다. UNIQUE 라 프로젝트마다 진행 중인 실행이 하나뿐이다.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'PRGRS_PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '실행을 요청한 사용자 (로그인 정보에서 가져온다).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'ACNT_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '실행 상태 : PENDING(대기) · RUNNING(실행 중) · COMPLETED(결과 확정) · FAILED(실패) · INTERRUPTED(서버 재시작 등으로 중단).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'EXCN_STTS_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '사용자가 실행을 요청한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'DMND_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '실행기가 실행을 시작하고 적용 규칙을 확정한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'BGNG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '검사 기준 시각 : 판정에 쓴 읽기 스냅숏을 잡은 일시. 결과는 이 시점의 모델 기준이다.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'CRTR_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '실행이 끝난(확정·실패·중단) 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'END_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '실패·중단 사유 코드 (예 : INSPECTION_FAILED, SERVER_RESTARTED).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'ERR_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '실패·중단 사유의 요약 (비밀값·SQL 원문을 담지 않는다).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'ERR_CN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 처음 저장한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 고친 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 처음 저장한 사용자 아이디 (서버 작업은 SYSTEM).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 고친 사용자 아이디 (서버 작업은 SYSTEM).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;

