update TB_TBL set TASK_EXPLN = '한 실행에 실제로 적용한 규칙을 기록한다. 실행이 시작할 때 그때의 규칙 설정으로 확정하며(AI6-D28) 실행 중 설정이 바뀌어도 이 목록으로 판정한다. 규칙이 끝까지 판정되지 않으면(FAILED) 그 실행은 결과를 확정하지 않는다 (AI6-D32).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '검사 실행 규칙을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'INSP_EXCN_RULE_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '규칙을 적용한 검사 실행.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'INSP_EXCN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '적용한 품질 검사 규칙.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'RULE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '규칙 판정 상태 : RUNNING(판정 중) · COMPLETED(끝까지 판정·확정) · FAILED(판정 실패).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'EXCN_STTS_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 실행에서 이 규칙으로 발견한 검사 결과 수 (확정했을 때만).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'RSLT_CNT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 처음 저장한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 고친 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 처음 저장한 사용자 아이디 (서버 작업은 SYSTEM).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 고친 사용자 아이디 (서버 작업은 SYSTEM).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RULE' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;

