update TB_TBL set TASK_EXPLN = '한 실행이 규칙마다 만든 변화를 건수로 남긴다 (AI6-D09). NEW·PERSISTING·REOPENED 의 합이 발견 수이고, RULE_SATISFIED(실제 해결)와 TARGET_DELETED(대상 삭제)는 따로 센다 (AI6-D25). EXCLUDED 는 발견한 것 중 예외로 처리된 것의 수다. 실행별 전체 결과 목록은 저장하지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '검사 실행 결과를 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'INSP_EXCN_RSLT_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '건수를 낸 검사 실행.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'INSP_EXCN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '건수를 낸 규칙.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'RULE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '변화 유형 : NEW · PERSISTING · REOPENED · RULE_SATISFIED · TARGET_DELETED · EXCLUDED.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'CHG_TYPE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '그 유형의 검사 결과 수.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'RSLT_CNT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 처음 저장한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 고친 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 처음 저장한 사용자 아이디 (서버 작업은 SYSTEM).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 고친 사용자 아이디 (서버 작업은 SYSTEM).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;

