-- ---------- 예제 : 논리 모델 검사 결과 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 검사 결과 ----------
-- ---------- 예제 : 관계 (FK 마다 물리 관계 + 논리 관계 + 단일 컬럼 FK 는 속성 짝) 검사 결과 ----------
-- ---------- 예제 : UNIQUE·CHECK 제약조건 검사 결과 ----------
-- ---------- 예제 : 인덱스 검사 결과 (V4 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 검사 결과 ----------
update TB_TBL set TASK_EXPLN = '같은 문제를 fingerprint 로 식별해 한 행으로 관리한다 (AI6-D10). 실제 문제 상태(OPEN·RESOLVED)와 예외 여부는 따로이며(AI6-D24), 예외 처리한 문제가 다시 발견돼도 신규로 세지 않는다. 해결은 그 규칙을 끝까지 판정한 정상 실행에서만 판정하고, 대상이 지워진 경우는 TARGET_DELETED 로 실제 개선과 구분한다 (AI6-D13). 예외 변경은 버전 번호로 충돌을 막고, 검사 결과 반영은 예외 칼럼을 바꾸지 않는다 (AI6-D29).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '검사 결과를 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'INSP_RSLT_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '결과가 속한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '문제를 찾은 규칙.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'RULE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '규칙의 심각도 : ERROR · WARNING · INFO (규칙 정의 값, 프로젝트마다 바꿀 수 없다).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'RSLT_GRD_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '대표 대상의 종류 : COLUMN · TABLE · SCHEMA · TERM.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'TRGT_TYPE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '대표 대상의 일련번호 (용어 그룹은 가장 작은 구성원). 모든 대상은 근거의 targetIds 에 있다.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'TRGT_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '대상이 속한 테이블 (컬럼·테이블·식별자 문제, 대상별 조회용).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'TBL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '판정 당시 대상의 표시 이름 (스키마·테이블·컬럼·용어 그룹 키). 대상이 지워져도 남는다.' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'TRGT_CN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '같은 문제를 식별하는 fingerprint (v1 또는 용어 그룹 v2).' where PRJ_SN = 0 and TBL_NM = 'TB_INSP_RSLT' and COL_NM = 'HASH_VL' and TASK_EXPLN is null;
