insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 1 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'EXCN_STTS_CD' where upper(k.CNSTRT_NM) = 'CK_INSP_EXCN_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 1);
insert into TB_TBL_CNSTRT(CNSTRT_SN, PRJ_SN, TBL_SN, CNSTRT_NM, CNSTRT_TYPE_CD, INSP_EXPR_CN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_CNSTRT'), 0, t.TBL_SN, 'CK_INSP_EXCN_02', 'CHECK', '((((excn_stts_cd)::text = ANY ((ARRAY[''PENDING''::character varying, ''RUNNING''::character varying])::text[])) AND (prgrs_prj_sn IS NOT NULL) AND (prgrs_prj_sn = prj_sn)) OR (((excn_stts_cd)::text = ANY ((ARRAY[''COMPLETED''::character varying, ''FAILED''::character varying, ''INTERRUPTED''::character varying])::text[])) AND (prgrs_prj_sn IS NULL) AND (end_dt IS NOT NULL)))', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN' and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'EXCN_STTS_CD') and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'PRGRS_PRJ_SN') and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'PRJ_SN') and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'END_DT') and not exists (select 1 from TB_TBL_CNSTRT k where k.TBL_SN = t.TBL_SN and upper(k.CNSTRT_NM) = 'CK_INSP_EXCN_02');
