insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 1 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RULE' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'EXCN_STTS_CD' where upper(k.CNSTRT_NM) = 'CK_INSP_EXCN_RULE_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 1);
insert into TB_TBL(TBL_SN, PRJ_SN, SCHM_SN, TBL_NM, TBL_KORN_NM, TBL_EXPLN, MSTR_TBL_YN, SORT_ORD, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL'), 0, s.SCHM_SN, 'TB_INSP_EXCN_RSLT', '검사 실행 결과', '검사 실행 × 규칙 × 변화 유형별 건수 (신규·유지·재발·해결·대상 삭제·예외 적용, AI-6)', false, (select coalesce(max(SORT_ORD), 0) + 1 from TB_TBL where PRJ_SN = 0), true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_SCHM s where s.PRJ_SN = 0 and s.BSC_YN = true and not exists (select 1 from TB_TBL where PRJ_SN = 0 and TBL_NM = 'TB_INSP_EXCN_RSLT');
