insert into TB_LGCL_IDNTFR(LGCL_IDNTFR_SN, LGCL_ENTT_SN, IDNTFR_NM, BSC_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_IDNTFR'), e.LGCL_ENTT_SN, '검사 실행 결과 식별자', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '검사 실행 결과' and not exists (select 1 from TB_LGCL_IDNTFR i where i.LGCL_ENTT_SN = e.LGCL_ENTT_SN and i.BSC_YN = true);
insert into TB_LGCL_IDNTFR_ATRB(LGCL_IDNTFR_ATRB_SN, LGCL_IDNTFR_SN, LGCL_ATRB_SN, SORT_ORD) select nextval('SQ_LGCL_IDNTFR_ATRB'), i.LGCL_IDNTFR_SN, a.LGCL_ATRB_SN, 1 from TB_LGCL_IDNTFR i join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = i.LGCL_ENTT_SN and a.ATRB_NM = '검사 실행 결과 일련번호' where i.LGCL_ENTT_SN = (select LGCL_ENTT_SN from TB_LGCL_ENTT where LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ENTT_NM = '검사 실행 결과') and i.IDNTFR_NM = '검사 실행 결과 식별자' and not exists (select 1 from TB_LGCL_IDNTFR_ATRB x where x.LGCL_IDNTFR_SN = i.LGCL_IDNTFR_SN);
insert into TB_ENTT_TBL_MPNG(ENTT_TBL_MPNG_SN, PRJ_SN, LGCL_ENTT_SN, TBL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ENTT_TBL_MPNG'), 0, e.LGCL_ENTT_SN, t.TBL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA' join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RSLT' where e.PRJ_SN = 0 and e.ENTT_NM = '검사 실행 결과' and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN) and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_ATRB_COL_MPNG'), mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_ENTT_TBL_MPNG mp join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN and e.ENTT_NM = '검사 실행 결과' join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_NM = 'TB_INSP_EXCN_RSLT' join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN and c.COL_EXPLN = a.ATRB_NM where mp.PRJ_SN = 0 and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN) and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);
insert into TB_TBL_REL(REL_SN, PRJ_SN, ORGNL_TBL_SN, TRGT_TBL_SN, REL_NM, REL_TYPE_CD, REL_SRC_CD, DRVN_COL_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_REL'), 0, o.TBL_SN, t.TBL_SN, 'FK_INSP_EXCN_RSLT_01', 'FK', 'USER', null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL o join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN' where o.PRJ_SN = 0 and o.TBL_NM = 'TB_INSP_EXCN_RSLT' and not exists (select 1 from TB_TBL_REL r where r.PRJ_SN = 0 and r.ORGNL_TBL_SN = o.TBL_SN and upper(r.REL_NM) = 'FK_INSP_EXCN_RSLT_01');
insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select nextval('SQ_TBL_REL_COL'), r.REL_SN, oc.COL_SN, tc.COL_SN, 1 from TB_TBL_REL r join TB_TBL o on o.TBL_SN = r.ORGNL_TBL_SN and o.PRJ_SN = 0 and o.TBL_NM = 'TB_INSP_EXCN_RSLT' join TB_COL oc on oc.TBL_SN = r.ORGNL_TBL_SN and oc.COL_NM = 'INSP_EXCN_SN' join TB_COL tc on tc.TBL_SN = r.TRGT_TBL_SN and tc.COL_NM = 'INSP_EXCN_SN' where r.PRJ_SN = 0 and upper(r.REL_NM) = 'FK_INSP_EXCN_RSLT_01' and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN and x.COL_ORD = 1);
insert into TB_LGCL_REL(LGCL_REL_SN, PRJ_SN, LGCL_MDL_SN, ORGNL_ENTT_SN, TRGT_ENTT_SN, REL_NM, REL_EXPLN, IDNTF_YN, ORGNL_MIN_CNT, ORGNL_MAX_CNT, TRGT_MIN_CNT, TRGT_MAX_CNT, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL'), 0, pe.LGCL_MDL_SN, pe.LGCL_ENTT_SN, ce.LGCL_ENTT_SN, pt.TBL_KORN_NM, ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'INSP_EXCN_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조', case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('INSP_EXCN_SN') and c.PK_YN = false) then false else true end, case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('INSP_EXCN_SN') and c.NULL_ALWNC_YN = true) then 0 else 1 end, 1, 0, null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_INSP_EXCN' join TB_LGCL_ENTT ce on ce.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ce.ENTT_NM = ct.TBL_KORN_NM join TB_LGCL_ENTT pe on pe.LGCL_MDL_SN = ce.LGCL_MDL_SN and pe.ENTT_NM = pt.TBL_KORN_NM where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_INSP_EXCN_RSLT' and not exists (select 1 from TB_LGCL_REL x where x.LGCL_MDL_SN = ce.LGCL_MDL_SN and x.ORGNL_ENTT_SN = pe.LGCL_ENTT_SN and x.TRGT_ENTT_SN = ce.LGCL_ENTT_SN and x.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'INSP_EXCN_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조');
insert into TB_LGCL_REL_ATRB(LGCL_REL_ATRB_SN, LGCL_REL_SN, ORGNL_ATRB_SN, TRGT_ATRB_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_LGCL_REL_ATRB'), r.LGCL_REL_SN, pm.LGCL_ATRB_SN, cm.LGCL_ATRB_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_INSP_EXCN' join TB_COL cc on cc.TBL_SN = ct.TBL_SN and cc.COL_NM = 'INSP_EXCN_SN' join TB_COL pc on pc.TBL_SN = pt.TBL_SN and pc.COL_NM = 'INSP_EXCN_SN' join TB_ATRB_COL_MPNG cm on cm.COL_SN = cc.COL_SN join TB_ATRB_COL_MPNG pm on pm.COL_SN = pc.COL_SN join TB_LGCL_REL r on r.PRJ_SN = 0 and r.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'INSP_EXCN_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조' where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_INSP_EXCN_RSLT' and not exists (select 1 from TB_LGCL_REL_ATRB x where x.LGCL_REL_SN = r.LGCL_REL_SN);
insert into TB_TBL_CNSTRT(CNSTRT_SN, PRJ_SN, TBL_SN, CNSTRT_NM, CNSTRT_TYPE_CD, INSP_EXPR_CN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_CNSTRT'), 0, t.TBL_SN, 'UX_INSP_EXCN_RSLT_01', 'UNIQUE', null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RSLT' and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'INSP_EXCN_SN') and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'RULE_CD') and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'CHG_TYPE_CD') and not exists (select 1 from TB_TBL_CNSTRT k where k.TBL_SN = t.TBL_SN and upper(k.CNSTRT_NM) = 'UX_INSP_EXCN_RSLT_01');
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 1 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RSLT' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'INSP_EXCN_SN' where upper(k.CNSTRT_NM) = 'UX_INSP_EXCN_RSLT_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 1);
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 2 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RSLT' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'RULE_CD' where upper(k.CNSTRT_NM) = 'UX_INSP_EXCN_RSLT_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 2);
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 3 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RSLT' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'CHG_TYPE_CD' where upper(k.CNSTRT_NM) = 'UX_INSP_EXCN_RSLT_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 3);
insert into TB_TBL_CNSTRT(CNSTRT_SN, PRJ_SN, TBL_SN, CNSTRT_NM, CNSTRT_TYPE_CD, INSP_EXPR_CN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_CNSTRT'), 0, t.TBL_SN, 'CK_INSP_EXCN_RSLT_01', 'CHECK', '((chg_type_cd)::text = ANY ((ARRAY[''NEW''::character varying, ''PERSISTING''::character varying, ''REOPENED''::character varying, ''RULE_SATISFIED''::character varying, ''TARGET_DELETED''::character varying, ''EXCLUDED''::character varying])::text[]))', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RSLT' and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'CHG_TYPE_CD') and not exists (select 1 from TB_TBL_CNSTRT k where k.TBL_SN = t.TBL_SN and upper(k.CNSTRT_NM) = 'CK_INSP_EXCN_RSLT_01');
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 1 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RSLT' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'CHG_TYPE_CD' where upper(k.CNSTRT_NM) = 'CK_INSP_EXCN_RSLT_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 1);
insert into TB_TBL_CNSTRT(CNSTRT_SN, PRJ_SN, TBL_SN, CNSTRT_NM, CNSTRT_TYPE_CD, INSP_EXPR_CN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select nextval('SQ_TBL_CNSTRT'), 0, t.TBL_SN, 'CK_INSP_EXCN_RSLT_02', 'CHECK', '(rslt_cnt >= 0)', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_EXCN_RSLT' and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'RSLT_CNT') and not exists (select 1 from TB_TBL_CNSTRT k where k.TBL_SN = t.TBL_SN and upper(k.CNSTRT_NM) = 'CK_INSP_EXCN_RSLT_02');
