insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 4 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_RSLT_HSTRY' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'END_RSN_CD' where upper(k.CNSTRT_NM) = 'CK_INSP_RSLT_HSTRY_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 4);
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select nextval('SQ_TBL_CNSTRT_COL'), k.CNSTRT_SN, c.COL_SN, 5 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_INSP_RSLT_HSTRY' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'END_DT' where upper(k.CNSTRT_NM) = 'CK_INSP_RSLT_HSTRY_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 5);
